from collections import Counter
class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        counts = Counter(nums)
        result = []
        while counts:
            for value in sorted(counts):
                result.append(value)
                counts[value] -= 1
                if counts[value] == 0: del counts[value]
        return result

